import '@automattic/calypso-polyfills';
import { createExPlatClient } from '../src/create-explat-client';
import type { Config } from '../src/types';

(global as any).window = {};

console.log("Test: Caching - After TTL Expires");
console.log("=================================\n");

async function runTest(): Promise<void> {
    let networkCallCount = 0;

    const config: Config = {
        logError: () => {},
        fetchExperimentAssignment: async ({ experimentName }) => {
            networkCallCount++;
            const variation = 'variation_call_' + networkCallCount;
            console.log("[Network Call #" + networkCallCount + "] Returning: " + variation);
            return {
                ttl: 1,
                variations: { [experimentName]: variation }
            };
        },
        getAnonId: async () => 'user-expiry',
        isDevelopmentMode: false
    };

    const client = createExPlatClient(config);

    console.log("Request 1 (initial):");
    const result1 = await client.loadExperimentAssignment('expiry_exp');
    console.log("  Variation: " + result1.variationName);
    console.log("  TTL: " + result1.ttl + " second(s)");
    console.log("  Network calls: " + networkCallCount);

    console.log("\nRequest 2 (immediately, should use cache):");
    const result2 = await client.loadExperimentAssignment('expiry_exp');
    console.log("  Variation: " + result2.variationName);
    console.log("  Network calls: " + networkCallCount);

    console.log("\nWaiting 2 seconds for cache to expire...");
    await new Promise(resolve => setTimeout(resolve, 2000));

    console.log("\nRequest 3 (after TTL expired):");
    const result3 = await client.loadExperimentAssignment('expiry_exp');
    console.log("  Variation: " + result3.variationName);
    console.log("  Network calls: " + networkCallCount);

    console.log("\nSummary:");
    console.log("  Before expiry - used cache: " + (result1.variationName === result2.variationName));
    console.log("  After expiry - made new call: " + (networkCallCount > 1));
    console.log("  New variation received: " + (result3.variationName !== result1.variationName));
}

